# MT4113 Assignment 2: data for each group.
# group_data(group) returns a data frame with one row per patient:
#   practice  the GP practice (a factor)
#   age       the patient's age, standardised to mean 0 and SD 1
#   attended  1 if the patient attended their follow-up appointment, 0 if not
# Do not edit this file.
group_data <- function(group) {
  if (!is.numeric(group) || length(group) != 1 || group < 1 || group != round(group)) {
    stop("`group` must be your group number, a positive whole number.")
  }
  old <- if (exists(".Random.seed", envir = globalenv())) get(".Random.seed", envir = globalenv())
  on.exit(if (!is.null(old)) assign(".Random.seed", old, envir = globalenv()))
  set.seed(4113 + 1000 * group)
  J <- 60
  beta0 <- runif(1, -1, 0)
  beta1 <- runif(1, 0.4, 0.9)
  sigma <- runif(1, 1.2, 2)
  m <- sample(2:12, J, replace = TRUE)
  practice <- rep(seq_len(J), times = m)
  age <- round(rnorm(length(practice)), 2)
  u <- rnorm(J, 0, sigma)
  attended <- rbinom(length(practice), 1, plogis(beta0 + beta1 * age + u[practice]))
  data.frame(practice = factor(practice), age = age, attended = attended)
}
